{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Niraparib absolute oral bioavailability was 72.7% (90% CI 61.69–83.40) in patients after a 300 mg oral dose versus IV 14C-niraparib, supporting high F for a small-molecule oral drug with heteroaromatic/basic amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib absolute bioavailability was 72.3% (90% CI 50.0–104.6%) for a 2 mg oral tablet versus an i.v. microtracer in patients with solid tumours, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib absolute bioavailability was 75% in humans at 60 mg, supporting high F for a kinase inhibitor with an aminopyridine/heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib mean absolute bioavailability was 98% in healthy subjects and patients, supporting high F for an oral kinase inhibitor containing piperazine and aminopyrimidine motifs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam has high oral F due to complete absorption, negligible intestinal extraction and low hepatic extraction in humans, supporting high F for a small-molecule oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Predicted human pharmacokinetics for a cyclopentyl-containing heteroaromatic compound gave 80% oral F, moderately supporting high F for the query's cyclopentyl heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Brigatinib absolute bioavailability was 46% in healthy volunteers, still above the 20% threshold and supportive of high F for an oral small-molecule kinase inhibitor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F >= 20%) based on multiple transferable small-molecule oral drugs with absolute F values of 46–98%; no transferable evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule is present in the visible evidence.",
    "Most supporting records are from different chemical series; structural and mechanistic transfer is analogical rather than direct.",
    "One supporting record is a predicted human PK value rather than an experimental measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

